//! Deferred generated U32 file input and native13 continuation.
use super::*;
#[path="../../../engine/src/accounted_plain_integer_hierarchy_test_support.rs"]mod f;
use std::sync::atomic::{AtomicU64,Ordering};
struct Directory(std::path::PathBuf);
impl Directory{fn new()->Self{static NEXT:AtomicU64=AtomicU64::new(0);let p=std::env::temp_dir().join(format!("photocraft-u32-hierarchy-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir(&p).unwrap();Self(p)}}
impl Drop for Directory{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
#[test]
#[ignore="UNRUN/uncompiled generated U32/350 Source file open, select/metadata/disclosure/history and native13 SaveAs/title/reopen exact native/source custody; filter/pixel routes stay closed. No producer oracle."]
fn u32_hierarchy_headless_native_continues(){
 let dir=Directory::new();let source=dir.0.join("u32.xcf");std::fs::write(&source,f::bytes(2)).unwrap();let mut h=Headless::trusted_local();drop(h.open_owned_xcf_keep_current_bounded(&source).unwrap());let before=h.session.active().unwrap().doc.clone();f::observed(&before,2);assert!(before.accounted().unwrap().is_readonly_normal_hierarchy_storage());let(group,leaf,empty)=f::ids(&before);let source_id=h.session.active().unwrap().source.clone();h.command_run("layer.select",serde_json::json!({"layer":leaf.0})).unwrap();h.command_run("layer.setProps",serde_json::json!({"layer":group.0,"name":"U32 native group","opacity":0.375})).unwrap();let past=h.session.active().unwrap().history.past_len();let rev=h.session.active().unwrap().revision;let journal=h.session.journal.len();h.command_run("layer.setExpanded",serde_json::json!({"layer":group.0,"expanded":false})).unwrap();assert_eq!(h.session.active().unwrap().history.past_len(),past);assert_eq!(h.session.active().unwrap().revision,rev);assert_eq!(h.session.journal.len(),journal);h.command_run("layer.select",serde_json::json!({"layer":empty.0})).unwrap();let changed=h.session.active().unwrap().doc.clone();f::payload(&before,&changed);f::observed(&changed,2);let output=dir.0.join("u32.pcraft");h.save_owned_native_active(Some(&output),Some("pcraft"),&f::ctl()).unwrap();let saved=h.session.active().unwrap().doc.clone();assert_eq!(saved.name,"u32.pcraft");assert_eq!(h.session.active().unwrap().source,source_id);let mut reopen=Headless::trusted_local();drop(reopen.open_owned_native_keep_current_bounded(&output).unwrap());let now=reopen.session.active().unwrap().doc.clone();f::same(&saved,&now);f::observed(&now,2);assert!(now.accounted().unwrap().is_readonly_normal_hierarchy_storage());h.command_run("edit.undo",serde_json::json!({})).unwrap();h.command_run("edit.redo",serde_json::json!({})).unwrap();let stable=h.session.active().unwrap().doc.clone();for(id,p)in [("paint.stroke",serde_json::json!({"points":[[1,1,1]]})),("xcf.filter.enable",serde_json::json!({"filterId":"1","enabled":false})),("select.all",serde_json::json!({}))]{assert!(h.command_run(id,p).is_err());assert!(stable.shares_state(&h.session.active().unwrap().doc));}
}
